T = {
'card19_title': ("Server Hacked Overnight", "Servidor hackeado esta noche"),
'card20_opt0_res0': ("Despite the grumblers, everyone turned on two-factor authentication.\n\nDid you know? With MFA (multi-factor authentication), a stolen password is no longer enough to log in.", "Pese a las quejas, todo el mundo ha activado la doble autenticación.\n\n¿Lo sabías? Con la MFA (autenticación multifactor), una contraseña robada ya no basta para conectarse."),
'card20_opt0_res1': ("Users complain and management asks you to go easy.\n\nDid you know? Changing habits takes teaching: explain why before you enforce it.", "Los usuarios se quejan y la dirección pide ir con calma.\n\n¿Lo sabías? Cambiar hábitos requiere pedagogía: se explica el porqué antes de imponer."),
'card20_opt0': ("Enforce strong passwords and two-factor authentication", "Imponer contraseñas fuertes y doble autenticación"),
'card20_opt1_res0': ("The server is protected, but nothing changed for the other accounts.\n\nDid you know? A good password is long: a 4-word passphrase beats \"P@ssw0rd\".", "El servidor está protegido, pero nada ha cambiado para las demás cuentas.\n\n¿Lo sabías? Una buena contraseña es larga: una frase de 4 palabras vale más que «P@ssw0rd»."),
'card20_opt1': ("Quietly change just that one", "Cambiar solo esa en silencio"),
'card20_text': ("{0.SimFirstName} discovers that the main server's password is… \"admin123\".", "{0.SimFirstName} descubre que la contraseña del servidor principal es… «admin123»."),
'card20_title': ("The \"admin123\" Password", "La contraseña «admin123»"),
'card21_opt0_res0': ("Audit done, the client is delighted and pays in full!\n\nDid you know? An audit ends with a report: the flaws found and how to fix them.", "¡Auditoría superada, el cliente está encantado y paga hasta el último céntimo!\n\n¿Lo sabías? Una auditoría termina con un informe: los fallos encontrados y cómo corregirlos."),
'card21_opt0_res1': ("The job was harder than expected. {0.SimFirstName} only gets partly paid.\n\nDid you know? Before a job, you clearly define the scope (what you're allowed to test).", "La misión era más difícil de lo previsto. A {0.SimFirstName} solo le pagan una parte.\n\n¿Lo sabías? Antes de una misión, se define bien el alcance (lo que se tiene derecho a probar)."),
'card21_opt0': ("Accept the job", "Aceptar la misión"),
'card21_opt1_res0': ("The boss appreciates {0.SimFirstName}'s loyalty.\n\nDid you know? Some contracts forbid working for other clients: always check.", "El jefe valora la lealtad de {0.SimFirstName}.\n\n¿Lo sabías? Algunos contratos prohíben trabajar para otros clientes: siempre hay que comprobarlo."),
'card21_opt1': ("Decline: the employer comes first", "Rechazar: el empleador es lo primero"),
'card21_text': ("A small company offers {0.SimFirstName} §2500 for a security audit this weekend.", "Una pequeña empresa ofrece 2500 § a {0.SimFirstName} por una auditoría de seguridad este fin de semana."),
'card21_title': ("Paid Weekend Audit", "Auditoría pagada en fin de semana"),
'card22_opt0_res0': ("Fix deployed in 10 minutes. {0.SimFirstName} is the hero of the day!\n\nDid you know? Fixing in production without testing is risky: it worked this time.", "Corrección en línea en 10 minutos. ¡{0.SimFirstName} es el héroe del día!\n\n¿Lo sabías? Corregir en producción sin probar es arriesgado: esta vez ha funcionado."),
'card22_opt0_res1': ("The fix breaks something else. Things get worse…\n\nDid you know? Always test a fix in a test environment before production.", "La corrección rompe otra cosa. La situación empeora…\n\n¿Lo sabías? Una corrección siempre se prueba en un entorno de pruebas antes de producción."),
'card22_opt0': ("Fix it directly in production", "Corregir directamente en producción"),
'card22_opt1_res0': ("Back to the previous version in 2 minutes. {0.SimFirstName} will fix it calmly on Monday.\n\nDid you know? Going back to the previous version is called a rollback. It's easy with Git and versioning.", "Vuelta a la versión anterior en 2 minutos. {0.SimFirstName} lo corregirá el lunes, con calma.\n\n¿Lo sabías? Volver a la versión anterior se llama rollback. Es fácil gracias a Git y al control de versiones."),
'card22_opt1': ("Roll back to the previous version", "Volver a la versión anterior"),
'card22_text': ("Friday, 5 PM: the app crashes for every customer.", "Viernes, 17:00: la aplicación falla para todos los clientes."),
'card22_title': ("Bug in Production!", "¡Bug en producción!"),
'card23_opt0_res0': ("{0.SimFirstName} finds a hidden security flaw. Nice catch!\n\nDid you know? Code review lets you find bugs before they reach customers.", "{0.SimFirstName} encuentra un fallo de seguridad oculto. ¡Bien visto!\n\n¿Lo sabías? La revisión de código (code review) permite encontrar bugs antes de que lleguen a los clientes."),
'card23_opt0_res1': ("Too long: {0.SimFirstName} doesn't finish in time.\n\nDid you know? Ask for small changes: 3000 lines at once is impossible to review properly.", "Demasiado largo: {0.SimFirstName} no termina a tiempo.\n\n¿Lo sabías? Se piden cambios pequeños: 3000 líneas de golpe es imposible revisarlas bien."),
'card23_opt0': ("Review it seriously", "Revisarlo en serio"),
'card23_opt1_res0': ("Nothing serious, this time.\n\nDid you know? Approving without reading is like signing a contract without reading it.", "Nada grave, esta vez.\n\n¿Lo sabías? Aprobar sin leer es como firmar un contrato sin leerlo."),
'card23_opt1_res1': ("The code deletes the test database… The whole team is stuck.\n\nDid you know? Automated tests block dangerous code before it gets merged.", "El código borra la base de datos de pruebas… Todo el equipo está bloqueado.\n\n¿Lo sabías? Las pruebas automáticas bloquean el código peligroso antes de fusionarlo."),
'card23_opt1': ("Approve without reading", "Aprobar sin leer"),
'card23_text': ("A colleague asks {0.SimFirstName} to approve their 3000-line change \"real quick, it's urgent\".", "Un compañero le pide a {0.SimFirstName} que apruebe su código de 3000 líneas «rápido, que es urgente»."),
'card23_title': ("Code Review", "Revisión de código"),
'card24_opt0_res0': ("{0.SimFirstName}'s team wins! A §1000 bonus as the prize.\n\nDid you know? At a hackathon, you quickly learn to work as a team and focus on what matters.", "¡El equipo de {0.SimFirstName} gana! Con una prima de 1000 § de premio.\n\n¿Lo sabías? En un hackathon se aprende rápido a trabajar en equipo y a ir a lo esencial."),
'card24_opt0_res1': ("No win, but {0.SimFirstName} learned a lot.\n\nDid you know? Hackathons are a great way to fill your portfolio (your GitHub, for example).", "No hay victoria, pero {0.SimFirstName} ha aprendido mucho.\n\n¿Lo sabías? Los hackathons son una forma excelente de llenar tu portafolio (tu GitHub, por ejemplo)."),
'card24_opt0': ("Take part", "Participar"),
'card24_opt1_res0': ("A well-deserved rest.\n\nDid you know? Work-life balance prevents burnout, which is very common among developers.", "Un descanso bien merecido.\n\n¿Lo sabías? El equilibrio entre vida laboral y personal evita el agotamiento, muy frecuente entre los desarrolladores."),
'card24_opt1': ("Stay home and rest", "Quedarse a descansar"),
'card24_text': ("The company is hosting a hackathon this weekend: 24 hours to build an app.", "La empresa organiza un hackathon este fin de semana: 24 horas para crear una aplicación."),
'card24_title': ("24-Hour Hackathon", "Hackathon de 24 h"),
'card25_opt0_res0': ("The docs are clear and the intern is self-sufficient. The whole team benefits.\n\nDid you know? An API is an \"entry door\" that lets two programs talk to each other.", "La documentación es clara y el becario es autónomo. Todo el equipo sale ganando.\n\n¿Lo sabías? Una API es una «puerta de entrada» que permite a dos programas comunicarse."),
'card25_opt0_res1': ("The docs are a bit confusing, but better than nothing.\n\nDid you know? Tools like Swagger generate part of the docs from the code.", "La documentación es algo confusa, pero mejor que nada.\n\n¿Lo sabías? Herramientas como Swagger generan parte de la documentación a partir del código."),
'card25_opt0': ("Write proper documentation", "Escribir una documentación de verdad"),
'card25_opt1_res0': ("The intern takes a week to understand.\n\nDid you know? Undocumented code is expensive: every newcomer has to rediscover everything.", "El becario tarda una semana en entenderlo.\n\n¿Lo sabías? El código sin documentar sale caro: cada recién llegado tiene que redescubrirlo todo."),
'card25_opt1': ("Tell them to read the code", "Decirle que lea el código"),
'card25_text': ("Nobody ever documented the company API. The new intern is completely lost.", "Nadie ha documentado nunca la API de la empresa. El nuevo becario está completamente perdido."),
'card25_title': ("The Undocumented API", "La API sin documentación"),
'card26_opt0_res0': ("The client agrees to one more week. Everyone breathes again.\n\nDid you know? Agile methods (Scrum) deliver in small pieces to adapt to changes.", "El cliente acepta una semana más. Todos respiran.\n\n¿Lo sabías? Las metodologías ágiles (Scrum) entregan por partes pequeñas para adaptarse a los cambios."),
'card26_opt0_res1': ("The client refuses and complains to the boss.\n\nDid you know? A signed specification protects both sides when things change.", "El cliente se niega y se queja al jefe.\n\n¿Lo sabías? Un pliego de condiciones firmado protege a ambas partes si hay cambios."),
'card26_opt0': ("Negotiate a new deadline", "Negociar un nuevo plazo"),
'card26_opt1_res0': ("Delivered on time! But {0.SimFirstName} is exhausted.\n\nDid you know? \"Crunch\" (working through the night) sometimes works, but ends up creating bugs.", "¡Entregado a tiempo! Pero {0.SimFirstName} está agotado.\n\n¿Lo sabías? El «crunch» (trabajar de noche) a veces funciona, pero acaba creando bugs."),
'card26_opt1_res1': ("The rushed code is full of bugs. The client is furious.\n\nDid you know? When you're tired, you make more mistakes: technical debt piles up.", "El código hecho deprisa está lleno de bugs. El cliente está furioso.\n\n¿Lo sabías? Cansado, se cometen más errores: la deuda técnica se acumula."),
'card26_opt1': ("Code it all overnight", "Programarlo todo durante la noche"),
'card26_text': ("The day before delivery, the client changes the ENTIRE specification.", "La víspera de la entrega, el cliente cambia TODO el pliego de condiciones."),
'card26_title': ("The Client Changes Everything", "El cliente lo cambia todo"),
'card27_opt0_res0': ("{0.SimFirstName} codes faster without losing quality.\n\nDid you know? AI can be wrong: the developer is still responsible for the code they ship.", "{0.SimFirstName} programa más rápido sin perder calidad.\n\n¿Lo sabías? Una IA puede equivocarse: el desarrollador sigue siendo responsable del código que entrega."),
'card27_opt0': ("Use it, but check every line", "Usarla, pero revisar cada línea"),
'card27_opt1_res0': ("It works… for now.\n\nDid you know? Copying code you don't understand is setting up bugs for later.", "Funciona… por ahora.\n\n¿Lo sabías? Copiar código que no se entiende es preparar bugs para más adelante."),
'card27_opt1_res1': ("The generated code contained a security flaw. Oops.\n\nDid you know? Classic flaws (like SQL injection) often hide in copy-pasted code.", "El código generado tenía un fallo de seguridad. Ups.\n\n¿Lo sabías? Los fallos clásicos (como la inyección SQL) suelen esconderse en código copiado y pegado."),
'card27_opt1': ("Copy-paste without reviewing", "Copiar y pegar sin revisar"),
'card27_text': ("The boss wants the whole team to use AI to code faster.", "El jefe quiere que todo el equipo use una IA para programar más rápido."),
'card27_title': ("The Coding AI", "La IA que programa"),
'card28_opt0_res0': ("Website delivered, client delighted… and so is the bank account!\n\nDid you know? As a freelancer, you write a precise quote before starting.", "Web entregada, cliente encantado… ¡y la cuenta bancaria también!\n\n¿Lo sabías? Como freelance, se hace un presupuesto preciso antes de empezar."),
'card28_opt0_res1': ("The project was bigger than expected: {0.SimFirstName} only gets partly paid.\n\nDid you know? Without a clear specification, a small project can quickly become huge.", "El proyecto era más grande de lo previsto: a {0.SimFirstName} solo le pagan una parte.\n\n¿Lo sabías? Sin un pliego de condiciones claro, un proyecto pequeño puede volverse enorme."),
'card28_opt0': ("Accept", "Aceptar"),
'card28_opt1_res0': ("The boss appreciates {0.SimFirstName}'s loyalty.\n\nDid you know? Many developers start freelancing on the side before going 100% independent.", "El jefe valora la lealtad de {0.SimFirstName}.\n\n¿Lo sabías? Muchos desarrolladores empiezan como freelance en paralelo antes de dedicarse al 100 %."),
'card28_opt1': ("Decline: the employer comes first", "Rechazar: el empleador es lo primero"),
'card28_text': ("A startup offers {0.SimFirstName} §2500 to build its website this weekend.", "Una startup ofrece 2500 § a {0.SimFirstName} por desarrollar su web este fin de semana."),
'card28_title': ("Freelance Gig", "Misión freelance"),
'card29_opt0_res0': ("The boss makes a counter-offer: a §1000 bonus to keep {0.SimFirstName}!\n\nDid you know? A competing offer is a good argument, but don't overuse it.", "El jefe hace una contraoferta: ¡una prima de 1000 § para quedarse con {0.SimFirstName}!\n\n¿Lo sabías? Una oferta de la competencia es un buen argumento, pero no hay que abusar."),
'card29_opt0_res1': ("The boss takes it badly: \"If you want to leave, there's the door!\"\n\nDid you know? You negotiate with facts (market salary, results) rather than threats.", "Al jefe le sienta mal: «¡Si te quieres ir, ahí tienes la puerta!»\n\n¿Lo sabías? Se negocia con hechos (salario de mercado, resultados) y no con amenazas."),
'card29_opt0': ("Use the offer to negotiate with the boss", "Usar la oferta para negociar con el jefe"),
'card29_opt1_res0': ("The startup goes bankrupt 4 months later. Good call!\n\nDid you know? Before accepting an offer, check the company's health (funding rounds, Glassdoor reviews…).", "La startup quiebra 4 meses después. ¡Buena decisión!\n\n¿Lo sabías? Antes de aceptar una oferta, uno se informa sobre la salud de la empresa (rondas de financiación, opiniones en Glassdoor…)."),
'card29_opt1': ("Politely decline", "Rechazar con educación"),
'card29_text': ("A recruiter contacts {0.SimFirstName} on LinkedIn: a startup offers 20% more salary, a foosball table and stock options… but the company only has 6 months of cash left.", "Un reclutador contacta a {0.SimFirstName} por LinkedIn: una startup ofrece un 20 % más de sueldo, un futbolín y stock options… pero a la empresa solo le quedan 6 meses de tesorería."),
'card29_title': ("A Headhunter Calls", "Llama un cazatalentos"),
'card30_opt0_res0': ("Test passed with flying colors! Even without changing jobs, {0.SimFirstName} gains confidence.\n\nDid you know? An IT services company \"rents out\" its engineers to clients: it's often where you start after your studies.", "¡Prueba superada con nota! Aunque no cambie de trabajo, {0.SimFirstName} gana confianza.\n\n¿Lo sabías? Una consultora tecnológica «alquila» a sus informáticos a clientes: suele ser donde se empieza al terminar los estudios."),
'card30_opt0_res1': ("The test was hard, but {0.SimFirstName} now knows what to work on.\n\nDid you know? Getting assessed from time to time helps you know where you stand.", "La prueba era difícil, pero {0.SimFirstName} ya sabe qué tiene que trabajar.\n\n¿Lo sabías? Evaluarse de vez en cuando ayuda a saber en qué punto se está."),
'card30_opt0': ("Take the technical test to check their level", "Hacer la prueba técnica para ver su nivel"),
'card30_opt1_res0': ("{0.SimFirstName} stays focused on the current job.\n\nDid you know? In-house or consulting: in-house you know one company well; at a consultancy you see lots of different settings.", "{0.SimFirstName} se centra en su trabajo actual.\n\n¿Lo sabías? En plantilla o en consultora: en plantilla conoces bien una sola empresa; en consultora ves muchos contextos distintos."),
'card30_opt1': ("Ignore the message", "Ignorar el mensaje"),
'card30_text': ("An IT services company wants to hire {0.SimFirstName}: a different client every 6 months, and a technical test to start.", "Una consultora tecnológica quiere contratar a {0.SimFirstName}: un cliente distinto cada 6 meses y, para empezar, una prueba técnica."),
'card30_title': ("An IT Consultancy's Offer", "La oferta de una consultora"),
'card31_opt0_res0': ("{0.SimFirstName} saw through the trap: it was industrial espionage. The boss congratulates them.\n\nDid you know? Employment contracts often include a confidentiality clause.", "{0.SimFirstName} ha visto la trampa: era espionaje industrial. El jefe le felicita.\n\n¿Lo sabías? Los contratos de trabajo suelen incluir una cláusula de confidencialidad."),
'card31_opt0': ("Stay vague and polite", "Mantenerse vago y educado"),
'card31_opt1_res0': ("The boss finds out… Official warning!\n\nDid you know? Disclosing confidential information can lead to dismissal for serious misconduct.", "El jefe se entera… ¡Amonestación oficial!\n\n¿Lo sabías? Revelar información confidencial puede acabar en despido por falta grave."),
'card31_opt1': ("Tell everything to impress", "Contarlo todo para impresionar"),
'card31_text': ("A recruiter from a competitor invites {0.SimFirstName} to lunch… and asks a lot of questions about the company's secret projects.", "Un reclutador de una empresa rival invita a comer a {0.SimFirstName}… y hace muchas preguntas sobre los proyectos secretos de su empresa."),
'card31_title': ("The Overly Curious Recruiter", "El reclutador demasiado curioso"),
'card32_opt0_res0': ("It was a virus! {0.SimFirstName}'s computer has to be reinstalled.\n\nDid you know? A \".pdf.exe\" file is a disguised program: the real extension is the last one.", "¡Era un virus! Hay que reinstalar el ordenador de {0.SimFirstName}.\n\n¿Lo sabías? Un archivo «.pdf.exe» es un programa disfrazado: la extensión real es la última."),
'card32_opt0': ("Open the document", "Abrir el documento"),
'card32_opt1_res0': ("Good catch! Hackers use fake job offers to trap their victims.\n\nDid you know? Showing file extensions in Windows helps you spot this kind of trap.", "¡Bien visto! Los atacantes usan falsas ofertas de empleo para engañar a sus víctimas.\n\n¿Lo sabías? Mostrar las extensiones de archivo en Windows ayuda a detectar este tipo de trampa."),
'card32_opt1': ("Report the email to security", "Avisar del correo a seguridad"),
'card32_text': ("{0.SimFirstName} gets an incredible job offer by email: §10,000 a month! All you have to do is open the job description \"Offer.pdf.exe\".", "{0.SimFirstName} recibe una oferta increíble por correo: ¡10 000 § al mes! Solo hay que abrir la descripción del puesto «Oferta.pdf.exe»."),
'card32_title': ("The Fake Recruiter", "El falso reclutador"),
'card33_opt0_res0': ("\"98% of tickets resolved, 2 projects delivered\": the manager is impressed. §500 bonus!\n\nDid you know? Hard numbers always convince more than \"I worked a lot\".", "«98 % de tickets resueltos, 2 proyectos entregados»: el responsable está impresionado. ¡Prima de 500 §!\n\n¿Lo sabías? Los resultados con cifras convencen siempre más que «he trabajado mucho»."),
'card33_opt0_res1': ("A good review, but nothing more.\n\nDid you know? The annual review is also the time to ask for training.", "Buena entrevista, pero sin más.\n\n¿Lo sabías? La entrevista anual también sirve para pedir formación."),
'card33_opt0': ("Come in with measurable achievements", "Llegar con sus logros en cifras"),
'card33_opt1_res0': ("{0.SimFirstName} can't remember what they did in March… The manager is left wanting more.\n\nDid you know? Noting your achievements throughout the year is a good habit (like a school portfolio!).", "{0.SimFirstName} ya no recuerda qué hizo en marzo… El responsable se queda con ganas de más.\n\n¿Lo sabías? Anotar tus logros a lo largo del año es un buen hábito (¡como un portafolio de estudios!)."),
'card33_opt1': ("Wing it", "Improvisar"),
'card33_text': ("It's {0.SimFirstName}'s annual review with their manager.", "Es la entrevista anual de {0.SimFirstName} con su responsable."),
'card33_title': ("The Annual Review", "La entrevista anual"),
'card34_opt0_res0': ("Granted! A §1000 bonus until the new payslip.\n\nDid you know? Websites and studies publish average IT salaries: they're good backup for your request.", "¡Concedido! Una prima de 1000 § mientras llega la nueva nómina.\n\n¿Lo sabías? Hay webs y estudios que publican los salarios medios de los empleos informáticos: son un buen apoyo."),
'card34_opt0_res1': ("\"Not this year, the budget is tight.\"\n\nDid you know? If the raise is refused, you can negotiate something else: training, remote work, equipment.", "«Este año no, el presupuesto está ajustado.»\n\n¿Lo sabías? Si te niegan el aumento, puedes negociar otra cosa: formación, teletrabajo, material."),
'card34_opt0': ("Ask for +10% backed by market salaries", "Pedir un +10 % con los salarios del mercado"),
'card34_opt1_res0': ("Nobody offered it…\n\nDid you know? At work, you often have to ask: raises rarely fall from the sky.", "Nadie lo ha propuesto…\n\n¿Lo sabías? En la empresa, a menudo hay que pedirlo: pocos aumentos caen del cielo."),
'card34_opt1': ("Wait for it to be offered", "Esperar a que lo propongan"),
'card34_text': ("{0.SimFirstName} hasn't had a raise in a year.", "Hace un año que {0.SimFirstName} no tiene un aumento."),
}
